            ans.push_back(intervals[idx++]);
        while(idx<intervals.size() and intervals[idx][0]<=newInterval[1])
        {
            newInterval[0]=min(newInterval[0],intervals[idx][0]);
            newInterval[1]=max(newInterval[1],intervals[idx][1]);
